package kr.jinsu.radio;

import android.content.res.Configuration;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.android.controller.ActivityController;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=28,manifest=Config.NONE)
@ConscryptMode(ConscryptMode.Mode.OFF)
public class AdaptiveLayoutTest {
 ActivityController<PlayerLayoutTest.OfflineActivity> lifecycle;PlayerLayoutTest.OfflineActivity activity;
 @After public void destroy(){if(lifecycle!=null){lifecycle.destroy();lifecycle=null;}RuntimeEnvironment.setQualifiers("");}
 void create(int width,int height){if(lifecycle!=null)lifecycle.destroy();RuntimeEnvironment.setQualifiers("w"+width+"dp-h"+height+"dp");lifecycle=Robolectric.buildActivity(PlayerLayoutTest.OfflineActivity.class).create();activity=lifecycle.get();layout(width,height);if(activity.stationScroll!=null)activity.stationScroll.getViewTreeObserver().dispatchOnPreDraw();}
 void layout(int width,int height){int w=activity.dp(width),h=activity.dp(height);activity.root.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));activity.root.layout(0,0,w,h);}
 TextView find(View view,String text){if(view instanceof TextView&&((TextView)view).getText().toString().equals(text))return (TextView)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){TextView match=find(group.getChildAt(i),text);if(match!=null)return match;}}return null;}
 int y(View view){int result=0;while(view!=null){result+=view.getTop()-view.getScrollY();view=view.getParent() instanceof View?(View)view.getParent():null;}return result;}
 @Test public void foldedPhoneAndPhoneLandscapeKeepCompactLayout(){for(int[] size:new int[][]{{412,915},{915,412}}){create(size[0],size[1]);assertFalse(activity.wide);assertNull(activity.stationPane);assertNull(activity.detailPane);assertEquals(14,activity.rowPrograms.size());}}
 @Test public void foldAndTabletBothOrientationsHaveSeparatePanes(){for(int[] size:new int[][]{{673,841},{841,673},{800,1280},{1280,800}}){create(size[0],size[1]);assertTrue(activity.wide);assertNotNull(activity.stationPane);assertNotNull(activity.detailPane);assertTrue(activity.stationPane.getWidth()<activity.dp(size[0])*.55f);assertTrue(activity.detailPane.getLeft()>=activity.stationPane.getRight());assertSame(activity.stationPane,activity.stationScroll.getParent());assertSame(activity.detailPane,activity.scroll.getParent());assertTrue(activity.scroll.getHeight()>0);assertTrue(activity.playerContent.getWidth()<=activity.dp(AdaptiveLayout.DETAIL_MAX_WIDTH));assertEquals(14,activity.rowPrograms.size());View dock=activity.root.findViewById(R.id.playback_bar);TextView button=find(activity.detailPane,"오늘의 편성표");assertNotNull(button);assertTrue(y(button)+button.getHeight()<=y(dock));}}
 @Test public void wideDescriptionScrollDoesNotMoveActionsOrStationList(){create(1280,800);String full="넓은 화면에서도 설명은 생략 없이 유지합니다. ".repeat(120);activity.programDescription.setText(full);layout(1280,800);TextView button=find(activity.detailPane,"오늘의 편성표");int buttonY=y(button),stationTop=y(activity.stationPane),listY=activity.stationScroll.getScrollY();activity.scroll.scrollTo(0,activity.playerContent.getHeight());assertTrue(activity.scroll.getScrollY()>0);assertEquals(buttonY,y(button));assertEquals(stationTop,y(activity.stationPane));assertEquals(listY,activity.stationScroll.getScrollY());assertEquals(full,activity.programDescription.getText().toString());}
 @Test public void scheduleSortingNeverReplacesTheStationList(){create(800,1280);activity.selected=RadioData.find("kbs21");activity.onlyFavorites=true;activity.favorites=new HashSet<>(Arrays.asList("kbs21","ytn"));activity.query="KBS";activity.screen="schedule";long now=System.currentTimeMillis();activity.schedules.put("kbs21",Collections.singletonList(new RadioData.Program("현재 프로그램","","","",now-1000,now+3600000)));activity.build();layout(800,1280);assertNotSame(activity.stationList,activity.scheduleListView);assertEquals(Collections.singleton("kbs21"),activity.rowPrograms.keySet());LinearLayout before=activity.scheduleListView;int count=activity.stationList.getChildCount();activity.renderSchedule();assertEquals(count,activity.stationList.getChildCount());activity.changeSort("name");assertSame(before,activity.scheduleListView);assertEquals("name",activity.sortOrder);assertEquals(Collections.singleton("kbs21"),activity.rowPrograms.keySet());}
 @Test public void resizingPreservesSelectionSortFilterAndListPosition(){create(1280,800);activity.selected=RadioData.find("ytn");activity.sortOrder="name_desc";activity.query="";activity.build();layout(1280,800);activity.stationScroll.getViewTreeObserver().dispatchOnPreDraw();activity.stationScroll.scrollTo(0,activity.dp(120));RadioData.Station selected=activity.selected;for(int[] size:new int[][]{{800,1280},{412,915},{673,841}}){RuntimeEnvironment.setQualifiers("w"+size[0]+"dp-h"+size[1]+"dp");activity.onConfigurationChanged(new Configuration(activity.getResources().getConfiguration()));layout(size[0],size[1]);activity.stationScroll.getViewTreeObserver().dispatchOnPreDraw();assertSame(selected,activity.selected);assertEquals("name_desc",activity.sortOrder);assertEquals("",activity.query);assertEquals(activity.dp(120),activity.stationScroll.getScrollY());}}
 @Test public void wideOpenPlayerDoesNotCreateHiddenNavigationStep(){create(800,1280);assertEquals("list",activity.screen);activity.openPlayer();assertEquals("list",activity.screen);activity.screen="schedule";activity.build();activity.navigateBack();assertEquals("list",activity.screen);assertNotNull(activity.programTitle);activity.openPlayer();assertEquals("list",activity.screen);}
 @Test public void pendingScrollRestoreSurvivesAnEarlyRebuild(){create(800,1280);activity.listReturnScrollY=activity.dp(120);activity.restoreListPosition=true;activity.build();activity.build();layout(800,1280);activity.stationScroll.getViewTreeObserver().dispatchOnPreDraw();assertEquals(activity.dp(120),activity.stationScroll.getScrollY());assertFalse(activity.restoreListPosition);}
 @Test public void selectedFavoriteUpdatesBothPanes(){create(800,1280);activity.favorites.clear();activity.build();assertEquals("star",activity.favoriteButton.icon);activity.toggleFavorite(activity.selected);activity.populate();assertEquals("starFilled",activity.favoriteButton.icon);assertTrue(activity.favorites.contains(activity.selected.id));activity.toggleFavorite(activity.selected);assertEquals("star",activity.favoriteButton.icon);}
 void gesture(View target,float from,float to){for(int i=0;i<4;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==3?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;float fraction=i==0?0:i==1?.5f:1;MotionEvent event=MotionEvent.obtain(0,i*50,action,activity.dp(from+(to-from)*fraction),activity.dp(150),0);try{target.dispatchTouchEvent(event);}finally{event.recycle();}}}
 @Test public void onlyWideDetailSwipeChangesChannel(){create(800,1280);gesture(activity.stationPane,220,60);assertEquals(0,activity.steps);gesture(activity.detailPane,300,60);assertEquals(1,activity.steps);assertEquals(1,activity.lastDirection);gesture(activity.detailPane,60,300);assertEquals(2,activity.steps);assertEquals(-1,activity.lastDirection);}
}
